CREATE TABLE IF NOT EXISTS items(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,sku TEXT,qty REAL NOT NULL DEFAULT 0,unit TEXT DEFAULT 'pcs',cost REAL NOT NULL DEFAULT 0,price REAL NOT NULL DEFAULT 0,reorder REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS assets(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,category TEXT,purchased TEXT,cost REAL NOT NULL DEFAULT 0,notes TEXT);
CREATE TABLE IF NOT EXISTS accounts(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,type TEXT DEFAULT 'Cash',opening REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS expenses(id INTEGER PRIMARY KEY AUTOINCREMENT,date TEXT NOT NULL,category TEXT,description TEXT,amount REAL NOT NULL DEFAULT 0,account_id INTEGER REFERENCES accounts(id));
CREATE TABLE IF NOT EXISTS transactions(id INTEGER PRIMARY KEY AUTOINCREMENT,account_id INTEGER NOT NULL REFERENCES accounts(id),date TEXT NOT NULL,description TEXT,amount REAL NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS ix_exp_date ON expenses(date);
CREATE INDEX IF NOT EXISTS ix_tx_acc ON transactions(account_id);
